using Captovix;
int count=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;}
var random=new Random(137);var a=new Annotation{Kind=AnnotationKind.Callout};
for(int i=0;i<2000;i++){double sx=random.Next(-1500,1500),sy=random.Next(-1000,1000),dx=random.Next(-900,900),dy=random.Next(-700,700);CalloutGesture.Place(a,sx,sy,sx+dx,sy+dy);Check(a.TailX==sx&&a.TailY==sy,"Initial tail stays pinned");Check(a.Width>=36&&a.Height>=36,"Body remains saveable");Check(Math.Abs(a.Width-Math.Max(CalloutGesture.MinimumSize,Math.Abs(dx)-Math.Min(18,Math.Abs(dx)*.2)))<.00001,"Width follows horizontal pointer independently");Check(Math.Abs(a.Height-Math.Max(CalloutGesture.MinimumSize,Math.Abs(dy)-Math.Min(18,Math.Abs(dy)*.2)))<.00001,"Height follows vertical pointer independently");}
for(int x=-400;x<=400;x++){CalloutGesture.Place(a,0,0,x,-180);Check(a.Height==162&&a.TailX==0&&a.TailY==0,"Continuous horizontal sweep keeps height and tail");}
var d=new EditorDocument{OriginalWidth=1920,OriginalHeight=1080,Annotations=[a]};var session=new EditorSession(d);session.Change(doc=>CalloutGesture.Place(doc.Annotations[0],10,100,450,-80));double width=a.Width;session.Undo();session.Redo();Check(session.Document.Annotations[0].Width==width&&session.Document.Annotations[0].TailX==10,"Undo/Redo preserves gesture geometry");Console.WriteLine($"PASS {count} callout geometry checks");
